(function(){'use strict';const q=(window.Q_PARTS||[]).find(x=>x.id==='sm2-5y-r05-law-10');if(!q||q.topic!=='産業医の辞任等の報告'||q.answer!==5)throw Error('HM2 canonical choice target/answer changed: '+(q?JSON.stringify({topic:q.topic,answer:q.answer}):'missing'));q.choices=["長時間労働時間の算定 ― 一般労働者の面接指導は、月80時間超などの要件に該当する労働者の申出により行う。","月80時間超の情報通知 ― 長時間労働者への面接指導結果の記録を5年間保存する。","産業医の辞任等の報告 ― 産業医の辞任・解任等があった場合、衛生委員会等への報告に加え、2026年8月1日施行の改正後は所轄労基署長への報告も行う。","面接指導結果記録の保存 ― 算定した時間外・休日労働が月80時間を超えた労働者へ、その時間数の情報を速やかに通知する。","長時間労働者の面接指導の申出 ― 面接指導後、事業者は医師から就業上の措置等に関する意見を遅滞なく聴く。"];const canonicalCorrect=q.choices.findIndex(c=>c.startsWith(q.topic+' ― '));if(canonicalCorrect!==2)throw Error('HM2 legal correct paired choice missing');[q.choices[canonicalCorrect],q.choices[q.answer-1]]=[q.choices[q.answer-1],q.choices[canonicalCorrect]];q.quick=q.topic+'：'+q.choices[q.answer-1].split(' ― ')[1];if(q.choices.length!==5||new Set(q.choices).size!==5)throw Error('HM2 canonical legal choices invalid');})();

