// HM2_P0_2_OCCUPATIONAL_PHYSICIAN_REDESIGN_20261111: replace mechanically mismatched choices with application-based alternatives; preserve existing release audit flags and source.
(function(){'use strict';
const target=(window.Q_PARTS||[]).find(x=>x.id==='sm2-5y-r05-law-10');
if(!target||target.topic!=='産業医の辞任等の報告'||target.subject!=='関係法令')throw Error('HM2 P0-2 target mismatch');
const choices=["産業医の辞任については、後任の産業医の選任が完了するまで所轄労働基準監督署長への報告を行う必要はない。","衛生委員会等に辞任の旨と理由を報告すれば、所轄労働基準監督署長への辞任の報告は必要ない。","辞任の旨と理由を遅滞なく衛生委員会等に報告し、産業医の氏名・辞任年月日等を遅滞なく所轄労働基準監督署長に報告する。","所轄労働基準監督署長への辞任の報告は電子申請に限られ、経過措置による書面での報告は認められない。","産業医の辞任については、所轄都道府県労働局長に14日以内に報告すれば、衛生委員会等への報告は必要ない。"];
if(choices.length!==5||new Set(choices).size!==5)throw Error('HM2 P0-2 choices invalid');
Object.assign(target,{question:"2026年8月1日以降、常時50人以上の労働者を使用し産業医の選任義務がある事業場で、産業医が辞任した。前任産業医の辞任に関する事項を含む後任者の選任報告を行っていない場合、事業者の対応として法令上、正しいものはどれか。",choices,answer:3,quick:"産業医が辞任したら、衛生委員会等には旨・理由を遅滞なく報告。選任報告で前任者の辞任事項を報告していない場合は、所轄労基署長にも遅滞なく報告。",explanation:"労働安全衛生規則13条4項により、産業医の辞任・解任時はその旨と理由を遅滞なく衛生委員会又は安全衛生委員会へ報告する。同条5項（2026年8月1日施行）は、産業医の選任義務がある事業場で辞任・解任・退任した産業医の氏名・年月日等を所轄労働基準監督署長へ遅滞なく報告する義務を定める。ただし同条2項の後任選任報告で前任者の辞任等の事項を報告した場合、辞任等の別途報告は不要。報告は原則電子申請だが、改正省令附則2項の経過措置として当分の間は必要事項を記録した書面で報告可能。第1肢は後任選任までの報告猶予がなく誤り、第2肢は署長報告を欠き、第4肢は書面の経過措置を否定し、第5肢は報告先・期限と委員会報告義務を誤る。根拠：安衛則13条2項・4項・5項、令和8年厚労省令86号、基発0428第4号。"});
window.HM2_P0_2_OCCUPATIONAL_PHYSICIAN_ID=target.id;
})();


