// HM2_P1_1_DIFFERENT_CONDITION_HEALTH_REPORT_20261111: differentiate the 49-vs-50 worker reporting threshold from 2025+ electronic submission. Preserve IDs, answer slots, review/publication flags.
(function(){'use strict';
const fixes=[{"id":"sm2-5y-r08-law-05","answer":3,"topic":"常時使用労働者49人と50人の定期健診結果報告義務","question":"常時使用する労働者が49人のA事業場と50人のB事業場で、いずれも一般の定期健康診断を実施した。安衛則上の健康診断実施義務と所轄労働基準監督署長への定期健康診断結果報告義務の組合せとして正しいものはどれか。","choices":["A・Bとも一般定期健康診断の実施義務はなく、結果報告義務もない。","Aのみ定期健康診断結果の報告義務があり、Bにはない。","A・Bとも対象労働者への一般定期健康診断は必要だが、定期健康診断結果を所轄労働基準監督署長へ報告する義務はBにある。","A・Bとも常時使用労働者100人未満なので、結果報告義務はない。","Bにのみ一般定期健康診断の実施義務があり、Aにはない。"],"quick":"一般定期健康診断の実施義務は50人未満でもあり、結果報告義務は常時50人以上の事業場にある。","explanation":"安衛則44条の一般定期健康診断は、常時使用労働者が50人未満でも対象となる労働者について事業者の実施義務がある。他方、同52条の定期健康診断結果を所轄労働基準監督署長へ遅滞なく報告する義務は常時50人以上の事業場に適用される。したがってA（49人）とB（50人）はともに健診を実施するが、結果報告義務の対象はBのみ。第1・5肢は健診実施義務の不存在を誤認し、第2肢は規模閾値を逆転させ、第4肢は100人という誤った閾値を用いている。Bの報告は2025年1月1日以降原則電子申請。根拠：安衛則44条・52条。","basis":"労働安全衛生規則44条・52条（健診実施義務と報告義務の規模閾値）","sourceUrl":"https://laws.e-gov.go.jp/law/347M50002000032"},{"id":"sm2-5y-r08-law-07","answer":2,"topic":"定期健康診断結果報告の電子申請手続","question":"2026年、常時60人の労働者を使用する事業場が一般の定期健康診断を実施し、個人票を作成・保存して労働者本人にも結果を通知した。電子申請を利用できる事業場が、この後に行う結果報告の対応として正しいものはどれか。","choices":["個人票の保存が済んだため、所轄労働基準監督署長への結果報告は不要である。","遅滞なく電子申請により、定期健康診断結果の所定事項を所轄労働基準監督署長へ報告する。","電子申請は選任報告に限られるため、定期健康診断結果報告は紙の提出のみが認められる。","本人への結果通知をした場合、定期健康診断結果報告は5年後まで延期できる。","健診結果は所轄労働基準監督署長ではなく都道府県知事にだけ報告する。"],"quick":"50人以上の定期健康診断結果報告は、個人票保存・本人通知とは別に、原則電子申請で遅滞なく所轄労基署長へ行う。","explanation":"安衛則52条により、常時50人以上の労働者を使用する事業場では、一般定期健康診断の結果について所定事項を遅滞なく所轄労働基準監督署長へ報告する。2025年1月1日から定期健康診断結果報告は原則電子申請が義務化されている。本問は電子申請が利用できる事業場なので第2肢が正しい。健康診断個人票の5年間保存（安衛則51条）と本人への結果通知（51条の4）は行政への結果報告とは別義務である。第1・4肢は保存や通知による免除・延期を誤り、第3肢は電子申請対象を誤り、第5肢は報告先を誤る。根拠：安衛則51条・51条の4・52条、厚生労働省の2025年1月電子申請義務化案内。","basis":"労働安全衛生規則51条・51条の4・52条／2025年1月1日電子申請義務化","sourceUrl":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/denshishinsei_00002.html"}];
const byId=new Map((window.Q_PARTS||[]).map(q=>[q.id,q]));
if(fixes.length!==2||new Set(fixes.map(f=>f.id)).size!==2)throw Error('HM2 P1-1 IDs invalid');
for(const f of fixes){
  const q=byId.get(f.id);
  if(!q||q.subject!=='関係法令')throw Error('HM2 P1-1 target/subject mismatch '+f.id);
  if(f.choices.length!==5||new Set(f.choices).size!==5||f.answer<1||f.answer>5)throw Error('HM2 P1-1 options invalid '+f.id);
  const alreadyRedesigned=q.answer===f.answer&&q.question===f.question&&JSON.stringify(q.choices)===JSON.stringify(f.choices);
  const legacy36Agreement=f.id==='sm2-5y-r08-law-05'&&q.answer===5&&/36協定|時間外.*休日労働|時間外労働/.test([q.question,...(Array.isArray(q.choices)?q.choices:[])].join('\n'));
  // The earlier cluster-C patch replaces the original stem with this intermediate health-report scenario.
  // Match both the exact intermediate stem and its correct fifth choice; do not accept an arbitrary answer-5 record.
  const intermediateHealthReport=f.id==='sm2-5y-r08-law-05'&&q.answer===5&&
    q.question==='常時使用する労働者50人の事業場が定期健康診断を実施した。結果報告に関して適切なのはどれか。'&&
    Array.isArray(q.choices)&&q.choices.length===5&&
    q.choices[4]==='所定の健康診断結果報告書を遅滞なく所轄労働基準監督署長に提出する。';
  const recognizedSource=alreadyRedesigned||legacy36Agreement||intermediateHealthReport;
  if(!recognizedSource&&q.answer!==f.answer)throw Error('HM2 P1-1 unexpected source/answer '+f.id);
  if(f.id==='sm2-5y-r08-law-05'&&!recognizedSource)throw Error('HM2 P1-1 unexpected source question '+f.id);
  Object.assign(q,{answer:f.answer,question:f.question,choices:f.choices,quick:f.quick,explanation:f.explanation,topic:f.topic,basis:f.basis,sourceUrl:f.sourceUrl});
}
window.HM2_P1_1_DIFFERENT_CONDITION_IDS=fixes.map(f=>f.id);
})();


