const HM2_P1_SOURCE_SIGNATURES={"sm2-5y-r04-law-02":{"answer":2,"correct":"選任すべき事由が発生した日から14日以内に選任する。","question":"常時使用する労働者が50人の事業場で、衛生管理者の選任期限として法令に適合するものはどれか。"},"sm2-5y-r10-law-04":{"answer":4,"correct":"選任すべき事由が生じた日から14日以内に選任する。","question":"常時55人の労働者がいる事業場で衛生管理者を選任する。事業者が満たすべき選任期限として適切なのはどれか。"},"sm2-5y-r06-law-07":{"answer":2,"correct":"5年間。","question":"事業者が一般健康診断を行って健康診断個人票を作成した。原則の保存期間として適切なのはどれか。"},"sm2-5y-r10-law-08":{"answer":3,"correct":"5年間保存する。","question":"常時60人の事務所が一般定期健康診断を実施した。健康診断個人票の法定保存期間として適切なのはどれか（特別な有害業務の健診を除く）。"},"sm2-5y-r04-hyg-08":{"answer":3,"correct":"28.6℃。","question":"屋外の清掃作業で湿球温度27℃、黒球温度33℃を測った（日射あり）。WBGTを0.7×湿球＋0.2×黒球＋0.1×気温で算出する場合、乾球気温31℃のWBGTはどれか。"},"sm2-5y-r04-hyg-10":{"answer":5,"correct":"約28.5℃","question":"日射がある屋外作業で自然湿球温度25℃、黒球温度38℃、気温34℃を測定した。屋外日射下の式で求めたWBGTに最も近い値はどれか。"},"sm2-5y-r05-hyg-06":{"answer":1,"correct":"画面の高さと机・椅子を調整し、肩を上げずに作業できる姿勢にする。","question":"情報機器作業者が午後になると肩・頸部の負担を訴える。画面が低く、机が高いため肩を上げて入力している。環境調整として適切なのはどれか。"},"sm2-5y-r06-hyg-03":{"answer":3,"correct":"画面高さや視距離を調整し、肩や首を無理に固定しない姿勢と作業休止を確保する。","question":"情報機器作業で首の前傾と肩のこりが増えたため、机・ディスプレイの配置を見直す。適切な改善策はどれか。"},"sm2-5y-r06-hyg-02":{"answer":2,"correct":"必要換気量を確認し、外気導入量や換気設備の運転を見直す。","question":"換気が不十分な会議室で、在室人数が増えると二酸化炭素濃度が上昇した。最初に検討すべき環境管理はどれか。"},"sm2-5y-r06-hyg-04":{"answer":4,"correct":"室内二酸化炭素濃度の推移。","question":"感染症対策として窓の開閉が難しい会議室に多数の人が集まる。換気の状況を把握するために活用し得る指標はどれか。"},"sm2-5y-r07-phy-06":{"answer":1,"correct":"グルカゴン","question":"食事を取れず血糖値が低下したとき、肝でのグリコーゲン分解等を促進し血糖を上げる方向に働く膵由来のホルモンはどれか。"},"sm2-5y-r07-phy-07":{"answer":2,"correct":"グルカゴンが肝臓のグリコーゲン分解や糖新生を促す。","question":"成人が空腹の状態で血糖値の低下をきたした。膵臓のα細胞から分泌されるホルモンの主な作用はどれか。"},"sm2-5y-r06-phy-07":{"answer":2,"correct":"集合管での水の再吸収を促し、尿量を減少させる。","question":"脱水が進むと下垂体後葉からの抗利尿ホルモンの分泌が高まりやすい。腎臓で生じる主な作用はどれか。"},"sm2-5y-r06-phy-09":{"answer":4,"correct":"抗利尿ホルモンの分泌が増え、腎集合管での水の再吸収が促進される。","question":"発汗が続いて体内の水分が減り、血漿浸透圧が上昇した。健常者で水分を保持する方向の反応として適切なのはどれか。"},"sm2-5y-r07-phy-08":{"answer":3,"correct":"バソプレシン（抗利尿ホルモン）―集合管の水透過性を高め、水の再吸収を促す。","question":"高温環境で大量に発汗した後、水分摂取が不足して血漿浸透圧が上昇した。腎臓での水の再吸収に関係するホルモンと作用の組合せとして適切なのはどれか。"},"sm2-5y-r05-phy-04":{"answer":4,"correct":"インスリン―骨格筋などへの糖取り込みの促進。","question":"食後に血糖が上昇した際、健常者で血糖を下げる方向に働くホルモンと主な作用の組合せはどれか。"},"sm2-5y-r05-phy-08":{"answer":3,"correct":"インスリン刺激によりGLUT4を含む小胞が細胞膜へ移動する。","question":"食後に血糖が上昇すると膵臓からインスリンが分泌される。筋細胞での糖取り込みが増加する直接的な機構として適切なのはどれか。"},"sm2-5y-r07-phy-02":{"answer":2,"correct":"筋・脂肪組織での糖取り込み等を促進し、血糖を下げる方向に働く。","question":"血糖値が上昇した食後、膵臓からのインスリン分泌が増えた。主な作用として適切なのはどれか。"},"sm2-5y-r07-phy-09":{"answer":4,"correct":"毛様体筋が収縮し、水晶体が厚くなる方向へ変化する。","question":"眼が遠くから近くの文字へ焦点を合わせるとき、正常な調節で生じる変化として適切なのはどれか。"},"sm2-5y-r08-phy-05":{"answer":5,"correctPrefix":"水晶体 ― "},"sm2-5y-r08-phy-10":{"answer":5,"correct":"虹彩の瞳孔括約筋","question":"眠っている間、急に明るい光を当てると瞳孔が小さくなった。この縮瞳に直接関与する筋はどれか。"},"sm2-5y-r09-phy-03":{"answer":3,"correct":"副交感神経―虹彩の瞳孔括約筋が収縮する。","question":"暗い室内から明るい屋外へ出たところ、瞳孔が縮小した。直接の縮瞳をもたらす自律神経と筋の組合せはどれか。"},"sm2-5y-r04-phy-08":{"answer":3,"correct":"4.2L/分。","question":"呼吸数が毎分12回、一回換気量が500mL、解剖学的死腔量が150mLである。単純化した毎分の肺胞換気量として最も近いのはどれか。"},"sm2-5y-r09-phy-04":{"answer":4,"correct":"一回換気量から解剖学的死腔量を差し引いた量と呼吸数。","question":"激しい運動後、呼吸数と換気量が増加した。肺胞換気量を求める際に考慮すべき量はどれか。"},"sm2-5y-r04-phy-06":{"answer":1,"correct":"血清","question":"血液を試験管内で凝固させ、凝固塊を除去して得た上清と、抗凝固剤を用いて分離した上清を比較した。前者の呼称はどれか。"},"sm2-5y-r04-phy-07":{"answer":2,"correct":"血漿。","question":"抗凝固剤を入れた採血管を遠心分離して血球成分を除いた上清を得た。凝固因子を含む上清の名称はどれか。"},"sm2-5y-r08-phy-02":{"answer":2,"correct":"錐体細胞","question":"薄暗い倉庫から屋外の明るい場所へ移動した。明所で色の違いを詳しく識別する働きを主に担う網膜の細胞はどれか。"},"sm2-5y-r08-phy-06":{"answer":1,"correct":"杆体・錐体の視細胞","question":"網膜に達した光が神経信号へ変換されるとき、最初に光を受容する細胞として適切なのはどれか。"},"sm2-5y-r08-phy-07":{"answer":2,"correctPrefix":"杆体 ― "},"sm2-5y-r08-phy-08":{"answer":3,"correctPrefix":"錐体 ― "},"sm2-5y-r04-phy-01":{"answer":1,"correct":"赤血球","question":"高地への移動後に酸素運搬が問題になった。血液中で酸素の大部分をヘモグロビンに結合して運ぶ成分として適切なのはどれか。"},"sm2-5y-r04-phy-02":{"answer":2,"correct":"赤血球のヘモグロビンが肺で酸素と可逆的に結合する。","question":"運動時、血液の酸素含有量を最も直接的に増加させる機序として適切なのはどれか（肺での酸素取り込みが正常である場合）。"},"sm2-5y-r04-phy-09":{"answer":4,"correct":"酸素を結合して運ぶ能力。","question":"血液検査でヘモグロビン濃度が低下したとき、他の条件が同じなら直接低下しやすい血液の機能はどれか。"}};
function HM2_P1_RECOGNIZED_SOURCE(q,f){
  if(!q||q.fiveYearExpansion!==true||!Array.isArray(q.choices)||q.choices.length!==5||
     !Number.isInteger(q.answer)||q.answer<1||q.answer>5)return false;
  const already=q.answer===f.answer&&q.question===f.question&&
    JSON.stringify(q.choices)===JSON.stringify(f.choices);
  if(already)return true;
  const sig=HM2_P1_SOURCE_SIGNATURES[f.id];
  if(!sig||q.answer!==sig.answer)return false;
  if(sig.question!==undefined&&q.question!==sig.question)return false;
  const correct=q.choices[q.answer-1];
  if(sig.correct!==undefined&&correct!==sig.correct)return false;
  if(sig.correctPrefix!==undefined&&
     (typeof correct!=='string'||!correct.startsWith(sig.correctPrefix)))return false;
  return true;
}

